    foreach(['utf8','utf8mb4'] as $charset){$db='kobi_phase319_metadata_'.$charset;oAssert((int)$p->query("SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='$db'")->fetchColumn()===0,'Fresh isolated database required.');$p->exec("CREATE DATABASE $db CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci");$p->exec('USE '.$db);$r=oImport($p,$filtered);oAssert($r['warnings']===[],'Base-schema warning.');$before=mf319Inventory($p);
        // The utf8 arm reproduces the original prefix exactly. The utf8mb4 arm
        // deliberately restores the normal PDO creation context on this isolated connection.
        if($charset==='utf8mb4'){$p->exec('SET NAMES utf8mb4 COLLATE utf8mb4_general_ci');oAssert($p->query('SHOW WARNINGS')->fetchAll()===[],'Context setup warning.');}
        $creation=mf319Inventory($p);$attempts=[];$diagnostics=[];$migration=oImport($p,$ddl,function($sql,$n)use(&$attempts){$attempts[]=['number'=>$n,'sql'=>$sql];},function($entry)use(&$diagnostics){$diagnostics[]=$entry;oAssert($entry['succeeded']&&$entry['warnings']===[],'Migration condition; stop.');});oAssert($migration['statements']===4&&$migration['warnings']===[],'Exact four-statement migration required.');$after=mf319Inventory($p);$meta=oMeta($p);$new=array_values(array_filter($meta['triggers'],fn($t)=>$t['EVENT_OBJECT_TABLE']===P319_TABLE));$shows=array_intersect_key($after['show_create'],oLoad('phase319-final-expected.json')['show_create']);$expected=['definition'=>$meta['definitions'][P319_TABLE],'triggers'=>$new,'show_create'=>$shows];$reference=$charset==='utf8'?oLoad('phase319-final-expected.json'):['definition'=>$normal['capture']['metadata']['definitions'][P319_TABLE],'triggers'=>array_values(array_filter($normal['capture']['metadata']['triggers'],fn($t)=>$t['EVENT_OBJECT_TABLE']===P319_TABLE)),'show_create'=>array_intersect_key($normal['capture']['triggers'],$shows)];foreach($expected as $k=>$v){oAssert($v===$reference[$k],'Reproduced metadata differs: '.$charset.'/'.$k);}
        $proof['rehearsals'][$charset]=['database'=>$db,'before'=>$before,'creation'=>$creation,'after'=>$after,'base_statements'=>$r['statements'],'migration'=>$migration,'attempted'=>$attempts,'diagnostics'=>$diagnostics,'expected'=>$expected,'reference_matches'=>true];
    }
    oSave('phase319-metadata-rehearsals.json',$proof);echo json_encode(['status'=>'ROOT_CAUSE_REPRODUCED','normal_ddl'=>0,'arms'=>['utf8'=>'original rehearsal exact match','utf8mb4'=>'normal deployed metadata exact match']],JSON_PRETTY_PRINT).PHP_EOL;
}
function mf319Certify():void {
