    $normalize=function(array $rows){$out=[];foreach($rows as $r){if($r['EVENT_OBJECT_TABLE']!==P319_TABLE){continue;}unset($r['TRIGGER_SCHEMA'],$r['EVENT_OBJECT_SCHEMA'],$r['CREATED']);$out[]=$r;}return $out;};$rows=$normalize($arm['after']['information_schema']);oAssert($rows===$normalize($normal['inventory']['information_schema']),'Complete trigger metadata differs.');oAssert(!preg_match('/[^\x00-\x7f]/',p319Artifacts()),'Non-ASCII SQL needs further literal analysis.');$cert=['status'=>'CERTIFIED','migration_sha256'=>P319_HASH,'normal_ddl'=>0,'normal_data_writes'=>0,'authoritative_context'=>$arm['creation']['state'],'database_context'=>$arm['creation']['database_state'],'expected'=>$arm['expected'],'normalized_information_schema'=>$rows,'semantic_certificate_sha256'=>hash_file('sha256',O_DIR.'/phase319-metadata-semantics.json'),'rehearsal_certificate_sha256'=>hash_file('sha256',O_DIR.'/phase319-metadata-rehearsals.json'),'normal_capture'=>$normal['capture']];oAssert(!file_exists(O_DIR.'/phase319-metadata-certified.json'),'Never overwrite certificate.');oSave('phase319-metadata-certified.json',$cert);echo "TRIGGER_METADATA_CERTIFIED; normal corrective DDL=0\n";
}
