        foreach(medicineProvisionalCandidates() as $id=>$name){$q=$p->prepare("INSERT INTO kobi_substances(substance_id,canonical_name,canonical_name_normalized,description) VALUES(?,?,?,?)");$q->execute([$id,$name,strtolower($name),$unicode]);}
